return {api_version=1,id="EX1_392",name="Battle Rage",text="Draw a card for each damaged friendly character.",set="EXPERT1",type="spell",class="warrior",rarity="common",cost=2,on_play=function(ctx,self)local p=ctx:controller(self);local n=ctx:entity(ctx:player(p).hero).damage>0 and 1 or 0;for _,e in ipairs(ctx:friendly_minions(self))do if ctx:entity(e).damage>0 then n=n+1 end end;if n>0 then ctx:draw(p,n)end end}
